import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_hash = hashlib.sha256(b'admin_secret_2024').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, email, role, api_key) VALUES (?, ?, ?, ?, ?)",
               ('admin', admin_hash, 'admin@internal.corp', 'superadmin', os.urandom(32).hex()))
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Basic field validation - only allow searching specific columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    if not value:
        return jsonify({'error': 'Query parameter required'}), 400

    # Log the search attempt
    db = get_db()
    db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
               ('search', f'field={field}, q={value}'))
    db.commit()

    # Construct and execute search query
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"
    try:
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/users/profile', methods=['GET'])
def get_profile():
    """Get user profile by API key"""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    # Parameterized query here - not vulnerable
    user = db.execute("SELECT username, email, role FROM users WHERE api_key = ?", (api_key,)).fetchone()
    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    return jsonify(dict(user))

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

@app.route('/internal/metrics', methods=['GET'])
def metrics():
    """Internal metrics endpoint - should not be externally accessible"""
    db = get_db()
    user_count = db.execute("SELECT COUNT(*) FROM users").fetchone()[0]
    log_count = db.execute("SELECT COUNT(*) FROM audit_log").fetchone()[0]
    return jsonify({'users': user_count, 'audit_entries': log_count, 'db_path': DATABASE})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
